import { NVector3 } from '../../../../../../../lib/NJSCore';
// import { Blank } from './Blank';
export class Graph {
    nodes: Node[] = [];
    edges: Edge[] = [];
    m: NVector3;
    capture: Node | undefined = undefined;
    historyTimer = 0.0;
    collisionTrajectory: NVector3[] = [];
    constructor() {
        this.m = new NVector3(500, 500);
        this.AddNode(50, 50);
        this.AddNode(100, 100);
        this.AddNode(100, 50);
        this.AddEdge(this.nodes[0], this.nodes[1]);
        this.AddEdge(this.nodes[1], this.nodes[2]);
        this.AddEdge(this.nodes[2], this.nodes[0]);
    }
    UpdateLength(v: number) {
        for (let i = 0; i < this.edges.length; ++i) {
            this.edges[i].targetLength = v;
        }
    }
    MouseDown(x: number, y: number) {
        this.m.x = x;
        this.m.y = y;
        this.capture = this.FindNode(x, y);
    }
    MouseLeftClick(x: number, y: number) {
        const n = this.AddNode(x, y);
        const cn = this.FindCloseNode(n);
        if (cn) {
            this.AddEdge(n, cn);
        }
    }
    MouseMove(x: number, y: number) {
        this.m.x = x;
        this.m.y = y;
    }
    MouseDrag(x: number, y: number) {
        if (this.capture) {
            this.capture.v.x = x;
            this.capture.v.y = y;
        }
    }
    AddNode(x: number, y: number) {
        const n = new Node(new NVector3(x, y), NVector3.Zero(), 2);
        this.nodes.push(n);
        return n;
    }
    AddEdge(n0: Node, n1: Node) {
        const e = new Edge(n0, n1);
        this.edges.push(e);
        return e;
    }
    FindCloseNode(n: Node, dis: number = 150000) {
        let index = -1;
        for (let i = 0; i < this.nodes.length; ++i) {
            if (this.nodes[i] !== n) {
                let theDis = this.nodes[i].v.Distance(n.v);
                if (theDis < dis) {
                    dis = theDis;
                    index = i;
                }
            }
        }
        if (index !== -1) {
            return this.nodes[index];
        }
        return undefined;
    }
    FindNode(x: number, y: number) {
        this.m.x = x;
        this.m.y = y;
        for (let i = 0; i < this.nodes.length; ++i) {
            let theDis = this.nodes[i].v.Distance(this.m);
            if (theDis < 10) {
                this.capture = this.nodes[i];
                // console.log(this.capture.colNodes);
                return this.nodes[i];
            }
        }
        this.capture = undefined;
        return undefined;
    }
    public Move(atr: NVector3, damping: number, g: number = -0.3, dt: number) {
        // Vector3d dv = atr - n.p;
        // double dist = dv.Length;
        // dv.Unitize();
        // //  n.f = dv * (1.0 / (dist));
        // n.f = dv * Math.Exp(-0.001 * dist * dist) * 0.1;
        // n.Move(dt, damping);
        for (let i = 0; i < this.nodes.length; ++i) {
            const n = this.nodes[i];
            // n.f = Vector3d.ZAxis * g;
            n.f.x *= g;
            n.f.y *= g;
            n.f.z *= g;
            const dv = new NVector3(atr.x - n.v.x, atr.y - n.v.y, atr.z - n.v.z);
            const L = dv.Length();
            // console.log(L);
            dv.Unitize();
            const x = dv.x * Math.exp(-0.001 * L * L) * 10.1; // + Vector3d.ZAxis.x * g;
            const y = dv.y * Math.exp(-0.001 * L * L) * 10.1; // + Vector3d.ZAxis.y * g;
            const z = dv.z * Math.exp(-0.001 * L * L) * 10.1; // + Vector3d.ZAxis.z * g;
            if (!isNaN(x)) {
                n.f.x = x; // + Vector3d.ZAxis.x * g;
                n.f.y = y; // + Vector3d.ZAxis.y * g;
                n.f.z = z; // + Vector3d.ZAxis.z * g;
            }
            // console.log(dv.x, L );
            // console.log(dv.x * Math.exp(-0.1 * L * L) );
            // n.Move(dt, damping);
        }
        // foreach(Node n in nodes) {
        //     Vector3d dv = atr - n.p;
        //     double L = dv.Length;
        //     dv.Unitize();
        //     n.f = dv * Math.Exp(-0.001 * L * L) * 0.1 + Vector3d.ZAxis * g;
        //   }
        //   foreach(Edge e in edges) {
        //     e.ApplySpringForce();
        //   }
        //   foreach(Node n in nodes) {
        //     n.Move(dt, damping);
        //   }
        for (let i = 0; i < this.edges.length; ++i) {
            this.edges[i].ApplySpringForce();
        }
        for (let i = 0; i < this.nodes.length; ++i) {
            this.nodes[i].CheckLine(this.edges);
        }

        for (let j = 0; j < this.nodes.length ; ++j) {
            this.nodes[j].isCol = false;
        }

        for (let j = 0; j < this.nodes.length; ++j) {
            let n0 = this.nodes[j];
            for (let i = 0 ; i < this.nodes.length; ++i) {
                let n1 = this.nodes[i];
                if (n0 === n1) { continue; }
                if (n0.v.Distance(n1.v) < 40) {
                    const vec = NVector3.Sub(n0.u, n1.u);
                    // // const dis = NVector3.Distance(this.pos, n1.v);
                    const nor = NVector3.Normalize(vec);
                    // const falloff = 0.1; // NVector3.CalculateFalloff(n0.v, n1.v, 1, 0.1);
                    const velocity = NVector3.Scale(nor, 1);
                    n0.u = NVector3.Add(n0.u, velocity);

                    // const vec = NVector3.Sub(this.vec, this.listCollision[i].vec);
                    // // const dis = NVector3.Distance(this.vec, this.listCollision[i].vec);
                    // const nor = NVector3.Normalize(vec);
                    // // const falloff = NVector3.CalculateFalloff(this.vec, this.listCollision[i].vec, dis, 0.1);
                    // this.velocity = NVector3.Scale(nor, Math.random() * this.graph.optiLevel);
                    // // console.log(this.velocity.x);
                    // this.vec = NVector3.Add(this.vec, this.velocity);
                    n0.isCol = true;
                    this.historyTimer += 0.1;
                    if (this.historyTimer  > 5 ) {
                        // console.log('the node', i , 'is within the node ', j  );
                        n0.colNodes.push(n1);

                        this.historyTimer = 0.0;

                        this.collisionTrajectory.push(new NVector3(n0.v.x, n0.v.y,  (Math.random() + 3) * 3)); // pos

                        const prob = Math.random();
                        if (prob < 0.3) {
                            this.collisionTrajectory.push(new NVector3(100, 0, 0)); // col
                        } else if (0.3 < prob && prob < 0.6) {
                            this.collisionTrajectory.push(new NVector3(0, 100, 0)); // col
                        } else {
                            this.collisionTrajectory.push(new NVector3(0, 0, 100)); // col
                        }
                    }
                    // console.log(velocity);
                } else {
                    // n0.isCol = false;
                }
            }
        }

        for (let i = 0; i < this.nodes.length; ++i) {
            this.nodes[i].Move(dt, damping);
        }
    }
    // .... vis
    Render(ctx: CanvasRenderingContext2D) {

        // ctx.  = 'lighter';
        for (let i = 0 ; i < this.collisionTrajectory.length; i += 2) {
            const v = this.collisionTrajectory[i];
            const c = this.collisionTrajectory[i + 1];
            ctx.beginPath();
            ctx.fillStyle = `rgba(${c.x}, ${c.y}, ${c.z}, 0.1)`;
            ctx.arc(v.x, v.y, v.z, 0, Math.PI * 2);
            ctx.closePath();
            ctx.fill();
        }
        // ctx.globalCompositeOperation = 'source-over';

        this.Move(this.m, 0.9, 0, 0.1);
        ctx.strokeStyle = '#000ff0';
        ctx.lineWidth = 1;
        for (let i = 0; i < this.edges.length; ++i) {
            ctx.beginPath();
            if (NVector3.Distance(this.edges[i].n0.v, this.edges[i].n1.v) < this.edges[i].targetLength - 5) {
                ctx.strokeStyle = '#ff0000';
                this.edges[i].n0.isShort = true;
                this.edges[i].n1.isShort = true;
            }
            ctx.moveTo(this.edges[i].n0.v.x, this.edges[i].n0.v.y);
            ctx.lineTo(this.edges[i].n1.v.x, this.edges[i].n1.v.y);
            ctx.closePath();
            ctx.stroke();
        }
        ctx.fillStyle = '#0000ff';
        for (let i = 0; i < this.nodes.length; ++i) {
            ctx.beginPath();
            if (this.nodes[i].isShort) {
                ctx.fillStyle = '#fff000';
                this.nodes[i].isShort = false;
            }
            ctx.arc(this.nodes[i].v.x, this.nodes[i].v.y, this.nodes[i].m * 5, 0, Math.PI * 2);
            ctx.closePath();
            ctx.fill();

            ctx.beginPath();
            ctx.arc(this.nodes[i].v.x, this.nodes[i].v.y, 20, 0, Math.PI * 2);
            ctx.closePath();
            if (this.nodes[i].isCol) {
                ctx.lineWidth = 4.5;
                ctx.strokeStyle = '#ff0000';
            } else {
                ctx.lineWidth = 1;
                ctx.strokeStyle = '#000000';
            }
            ctx.stroke();
        }
    }
}
class Edge {
    n0: Node;
    n1: Node;
    public targetLength: number = 1.05;
    public SpringConstant: number = 10.5;
    constructor(_n0: Node, _n1: Node) {
        this.n0 = _n0;
        this.n1 = _n1;
        const dis = this.n0.v.Distance(this.n1.v) - 10;
        this.targetLength = dis < 50 ? 60 : dis;
    }
    public ApplySpringForce() {
        const dp: NVector3 = new NVector3(this.n1.v.x - this.n0.v.x, this.n1.v.y - this.n0.v.y, this.n1.v.z - this.n0.v.z);
        const dist: number = dp.Length();
        dp.Unitize();
        this.n0.f.x += dp.x * (dist - this.targetLength) * this.SpringConstant;
        this.n0.f.y += dp.y * (dist - this.targetLength) * this.SpringConstant;
        this.n0.f.z += dp.z * (dist - this.targetLength) * this.SpringConstant;
        this.n1.f.x -= dp.x * (dist - this.targetLength) * this.SpringConstant;
        this.n1.f.y -= dp.y * (dist - this.targetLength) * this.SpringConstant;
        this.n1.f.z -= dp.z * (dist - this.targetLength) * this.SpringConstant;
    }
}
export class Node {
    fixed: boolean = false;
    needCompute: boolean = true;
    v: NVector3;
    u: NVector3;
    f: NVector3;
    m: number = 1;
    isShort: boolean = false;
    isCol: boolean = false;
    colNodes: Node[] = [];
    constructor(v: NVector3, u: NVector3, mass: number = 1) {
        this.v = v;
        this.u = u;
        this.f = NVector3.Origin();
        this.m = mass;
    }
    public Move(dt: number = 0.5, damping: number = 0.99) {
        if (this.fixed) { return; }
        // if (!this.needCompute) { this.needCompute = true; return; }
        this.u.x *= damping;
        this.u.y *= damping;
        this.u.z *= damping;

        this.u.x += this.f.x * (dt / this.m);
        this.u.y += this.f.y * (dt / this.m);
        this.u.z += this.f.z * (dt / this.m);

        this.v.x += this.u.x * dt;
        this.v.y += this.u.y * dt;
        this.v.z += this.u.z * dt;

        // console.log(this.u);
        // console.log(this.f);
        // console.log(this.v.x, this.v.y);
        // if (this.v.y < 0.0) {
        //     this.v.y = 0.0;
        //     if (this.u.y < 0.0) { this.u.y = -this.u.y; }
        // }
        this.needCompute = true;
    }
    public CheckLine(edges: Edge[]) {
        for (let i = 0; i < edges.length; ++i) {
            let e = edges[i];
            if (e.n0 !== this && e.n1 !== this) {
                const dis = this.PointCloseToLine(e.n0.v, e.n1.v, this.v);
                if (dis[0]) {
                    const p = new NVector3(dis[0], dis[1]);
                    const dis2 = p.Distance(this.v);
                    if (dis2 < 5) {
                        this.needCompute = false;
                        // console.log(dis2);
                        //    this.f.x *= -1;
                        //    this.f.y *= -1;
                        //    this.f.z *= -1;
                        p.Unitize();
                        const nv = NVector3.Normalize(this.v);

                        const vv = new NVector3(p.x - nv.x, p.y - nv.y, p.z - nv.z);
                        this.f = vv;
                        // this.v.x += vv.x ;
                        // this.v.y += vv.y ;
                    }
                }
            }
        }
    }
    public PointCloseToLine(p: NVector3, n0: NVector3, n1: NVector3) {
        let dx = n1.x - n0.x,
            dy = n1.y - n0.y,
            t = ((p.x - n0.x) * dx + (p.y - n0.y) * dy) / (dx * dx + dy * dy),
            x = this.Lerp(n0.x, n1.x, t),
            y = this.Lerp(n0.y, n1.y, t);
        return [x, y];
    }
    public Lerp(a: number, b: number, t: number) { return a + t * (b - a); }
}